    _buildCompletionHTML(summary) {
      summary = summary || {};
      var self = this;
      var fc = summary.finalComposite || 0;
      var ac = summary.avgComposite || 0;
      var tierKey = "perf_" + this._tierKey(fc, ac);
      var sim = window.mySimulation;
      var dx = summary._dx || (sim && sim.state && sim.state.history ? this._diagnose(sim.state.history) : { mistakes: [], gainRound: 1, gainDelta: 0 });
      var rows = [
        ["comp_eri_label", summary.eriScore || 0],
        ["comp_fs_label", summary.fsScore || 0],
        ["comp_scr_label", summary.scrScore || 0],
        ["comp_sta_label", summary.staScore || 0],
      ]
        .map(function (r) {
          return (
            '<div class="greenforge-completion-row"><span>' +
            self._t(r[0]) +
            '</span><span class="greenforge-completion-val">' +
            r[1] +
            "</span></div>"
          );
        })
        .join("");
      var iKeys = [
        summary.eriScore >= 50 ? "insight_eri_hi" : "insight_eri_lo",
        summary.fsScore >= 60 ? "insight_fs_hi" : "insight_fs_lo",
        summary.scrScore >= 60 ? "insight_scr_hi" : "insight_scr_lo",
        summary.staScore >= 60 ? "insight_sta_hi" : "insight_sta_lo",
      ];
      var insights = iKeys
        .map(function (k) {
          return "<li>" + self._t(k) + "</li>";
        })
        .join("");
      var turning = dx.mistakes.length
        ? this._fmt("mk_" + dx.mistakes[0].id, dx.mistakes[0].p)
        : this._fmt("turning_good", { r: dx.gainRound, x: dx.gainDelta });
      var others = dx.mistakes
        .slice(1)
        .map(function (m) {
          return "<li>" + self._fmt("mk_" + m.id, m.p) + "</li>";
        })
        .join("");
      var questions = ["dq_1", "dq_2", "dq_3"]
        .map(function (k) {
          return "<li>" + self._t(k) + "</li>";
        })
        .join("");
      return (
        '<div class="greenforge-completion-card" role="status" aria-live="polite"><h3>' +
        this._t("completion_title") +
        "</h3>" +
        '<div class="greenforge-completion-tier">' +
        this._t("completion_rating_label") +
        ": <strong>" +
        this._t(tierKey) +
        "</strong></div>" +
        '<div class="greenforge-completion-composite">' +
        this._t("comp_final_label") +
        ": <strong>" +
        fc +
        "/100</strong> &nbsp; " +
        this._t("comp_avg_label") +
        ": " +
        ac +
        "/100</div>" +
        '<div class="greenforge-completion-scores">' +
        rows +
        "</div>" +
        '<h4 class="greenforge-completion-sub">' +
        this._t("turning_heading") +
        "</h4><p class=\"greenforge-completion-turning\">" +
        turning +
        "</p>" +
        (others ? '<h4 class="greenforge-completion-sub">' + this._t("also_heading") + '</h4><ul class="greenforge-completion-insights">' + others + "</ul>" : "") +
        '<h4 class="greenforge-completion-sub">' +
        this._t("insights_heading") +
        '</h4><ul class="greenforge-completion-insights">' +
        insights +
        "</ul>" +
        '<h4 class="greenforge-completion-sub">' +
        this._t("dq_heading") +
        '</h4><ol class="greenforge-completion-insights">' +
        questions +
        "</ol></div>"
      );
    }
    _showCompletion() {
      var sim = window.mySimulation;
